effect.shader:
void main(){
    float t=acTime*speed;
    float wave=sin(acScreenNorm.x*freq + t)*amp*0.08;
    float slope=cos(acScreenNorm.x*freq + t)*amp*freq*0.08;
    vec2 uv=vec2(acScreenNorm.x, acScreenNorm.y + wave);
    if(uv.y<0.0||uv.y>1.0){gl_FragColor=vec4(0.0);return;}
    vec4 col=texture2DCv(inputImg.texture, uv);
    vec3 nrm=normalize(vec3(-slope,1.0,0.0));
    float diff=clamp(dot(nrm, normalize(vec3(0.3,0.8,0.5))),0.0,1.0);
    col.rgb *= mix(1.0, 0.4+0.8*diff, light);
    gl_FragColor=col;
}
